edits.newText:
  t += dt;
  // relaxamento final: alternar separação bola-bola e clamp de parede
  // para garantir, ao final do substep, que não há nem sobreposição nem
  // penetração em relação ao ângulo final
  for (let pass = 0; pass < 4; pass++) {
    let any = false;
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i], b = balls[j];
        const dx = b.x - a.x, dy = b.y - a.y;
        const d2 = dx * dx + dy * dy;
        const minD = a.r + b.r;
        if (d2 > 0 && d2 < minD * minD) {
          const d = Math.sqrt(d2);
          const nx = dx / d, ny = dy / d;
          const pen = minD - d;
          const push = pen / 2 + (pass === 3 ? pen * 0.5 : 0); // último passe mais agressivo
          a.x -= nx * push * 0.5; a.y -= ny * push * 0.5;
          b.x += nx * push * 0.5; b.y += ny * push * 0.5;
          any = true;
        }
      }
    }
    const before = any;
    clampInside(balls, cx, cy, t * OMEGA);
    if (!before) break;
  }
}

