edits.newText:
// Projeção puramente posicional: garante que as bolas ficam dentro do polígono no ângulo dado
function clampInside(ballArray, cx, cy, angle, passes) {
  const verts = polyVertices(cx, cy, angle);
  for (let pass = 0; pass < (passes || 12); pass++) {
    let moved = false;
    for (const b of ballArray) {
      let minDist = Infinity, cpx = 0, cpy = 0;
      for (let i = 0; i < N_SIDES; i++) {
        const a = verts[i], c = verts[(i + 1) % N_SIDES];
        const p = closestOnSegment(b.x, b.y, a.x, a.y, c.x, c.y);
        const d = Math.hypot(b.x - p.x, b.y - p.y);
        if (d < minDist) { minDist = d; cpx = p.x; cpy = p.y; }
      }
      if (minDist < b.r) {
        let nx = cx - cpx, ny = cy - cpy;
        const nl = Math.hypot(nx, ny) || 1;
        nx /= nl; ny /= nl;
        b.x += nx * (b.r - minDist);
        b.y += ny * (b.r - minDist);
        moved = true;
      }
    }
    if (!moved) break;
  }
}

