}

edits.newText:
  t += dt;
  // relaxamento final: alternar separação bola-bola e clamp de parede para
  // garantir, ao final do substep, que não há nem sobreposição nem penetração
  for (let pass = 0; pass < 10; pass++) {
    // separação bola-bola (posicional)
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i], b = balls[j];
        const dx = b.x - a.x, dy = b.y - a.y;
        const d2 = dx * dx + dy * dy;
        const minD = a.r + b.r;
        if (d2 > 0 && d2 < minD * minD) {
          const d = Math.sqrt(d2);
          const nx = dx / d, ny = dy / d;
          const per = (minD - d) / 2;
          a.x -= nx * per; a.y -= ny * per;
          b.x += nx * per; b.y += ny * per;
        }
      }
    }
    if (!clampInside(balls, cx, cy, t * OMEGA, 6)) break;
  }
}

